import {demo,evaluate} from './engine.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>v===null?'Undefined':(v*100).toFixed(1)+'%';
const labels={accuracy:'Accuracy',precision:'Precision',recall:'Recall',fpr:'False-positive rate'},status={pass:'Pass',fail:'Fail',insufficient:'Insufficient evidence'};
let data=demo(),report;
function download(name,object){const url=URL.createObjectURL(new Blob([JSON.stringify(object,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function policy(){const p={confidence:$('confidence').checked,selectedRun:$('run').value,minRuns:Number($('minRuns').value)};for(const k of ['accuracy','precision','recall','fpr','maxSpread']){if($(k).value==='')throw Error('Fill in all policy targets.');p[k]=Number($(k).value)/100;}if(!Number.isInteger(p.minRuns)||p.minRuns<2||p.minRuns>50)throw Error('Minimum seeds must be an integer from 2 to 50.');return p;}
function assess(){try{report=evaluate(data,policy());$('error').textContent='';$('export').disabled=false;render();}catch(e){$('error').textContent=e.message;$('export').disabled=true;}}
function load(next){evaluate(next,{accuracy:.9,precision:.9,recall:.9,fpr:.1,maxSpread:.02,minRuns:3,confidence:true});data=next;$('run').innerHTML=data.runs.map(r=>`<option value="${esc(r.id)}">${esc(r.id)}</option>`).join('');$('dataset').textContent=`${data.name||'Imported predictions'} · ${data.runs[0].rows.length.toLocaleString()} samples · ${data.runs.length} runs`;assess();}
function render(){const r=report,cm=r.confusion;
  $('banner').className='banner '+r.overall;
  const title=r.overall==='fail'?'Requirements not met':r.overall==='pass'?'All configured checks passed':'More evidence is needed';
  $('banner').innerHTML=`<h2>${title}${r.split==='validation'?' · provisional':''}</h2><p>${r.performance==='fail'?'The selected model misses one or more performance targets.':r.performance==='insufficient'?'The point scores are not enough to establish the required performance.':'The selected model clears its performance gates.'} ${r.stability==='fail'?'Repeated training is outside your stability limits.':''} ${r.reproducibility==='insufficient'?'Exact reproducibility has not been established.':''}</p>`;
  $('cards').innerHTML=[['Classification',status[r.performance],pct(cm.accuracy.value)+' measured accuracy'],['Training stability',status[r.stability],(r.spread*100).toFixed(1)+' percentage-point spread'],['Reproducibility',r.reproducibility==='insufficient'?'Not established':status[r.reproducibility],r.comparableGroups+' comparable artifact groups']].map(([name,value,note])=>`<div class="card"><p>${name}</p><strong>${value}</strong><small>${note}</small></div>`).join('');
  $('split').textContent=r.split.toUpperCase()+' SET';
  $('gates').innerHTML=r.gates.map(g=>`<tr><td>${labels[g.key]}</td><td>${pct(g.value)}</td><td>${g.interval?g.interval.map(pct).join(' – '):'No denominator'}</td><td>${g.direction==='min'?'≥':'≤'} ${pct(g.target)}</td><td><span class="pill ${g.status}">${status[g.status]}</span></td></tr>`).join('');
  $('bars').innerHTML=r.runs.map(run=>`<div class="run"><div class="runhead"><span>${esc(run.id)}${run.id===r.selectedRun?' · selected':''}</span><strong>${pct(run.metrics.accuracy.value)}</strong></div><div class="bar"><span style="width:${run.metrics.accuracy.value*100}%"></span><i style="left:${r.policy.accuracy*100}%" title="Accuracy target"></i></div></div>`).join('');
  $('agreement').textContent=`Mean accuracy ${pct(r.mean)} · Pairwise prediction agreement ${pct(r.agreement)} · ${r.distinctSeeds} distinct recorded seeds. Red marker = target.`;
  $('matrix').innerHTML=[['True positives',cm.tp,false],['False negatives',cm.fn,true],['False positives',cm.fp,true],['True negatives',cm.tn,false]].map(([name,n,bad])=>`<div class="cell ${bad?'error':''}"><strong>${n.toLocaleString()}</strong><span>${name}</span></div>`).join('');
  $('repro-title').textContent=r.reproducibility==='insufficient'?'Similar scores do not prove identical training':r.reproducibility==='fail'?'Same recorded setup, different model artifacts':'Comparable model artifact hashes match';
  $('repro-copy').textContent=r.reproducibility==='insufficient'?'These results can measure stability. To check exact reproducibility, include repeated runs with the same seed and matching data, recipe, and environment fingerprints, plus their model artifact fingerprints.':r.reproducibility==='fail'?'At least one comparable group has different model hashes. Check the training environment, deterministic operations, and artifact serialization.':'The supplied hashes match within every comparable group. This supports artifact reproducibility for those recorded setups; it does not prove reproducibility on other hardware or verify the submitted hashes.';
}
$('assess').onclick=assess;$('run').onchange=assess;
for(const id of ['accuracy','precision','recall','fpr','maxSpread','minRuns','confidence'])$(id).onchange=assess;
$('example').insertAdjacentHTML('beforeend','<option value="trained">Actual training on synthetic data</option>');
$('example').onchange=async()=>{try{if($('example').value==='trained'){const response=await fetch('/trained-example.json');if(!response.ok)throw Error('Example could not be loaded.');load(await response.json());}else load(demo($('example').value));}catch(e){$('error').textContent=e.message;}};
$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Please use a JSON file smaller than 10 MB.');load(JSON.parse(await file.text()));}catch(e){$('error').textContent='Import failed: '+e.message;}};
$('sample').onclick=()=>download('classification-predictions.json',demo('strong'));
$('export').onclick=()=>{assess();if(!$('export').disabled)download('classification-assessment.json',report);};
load(data);
